import re
writes=collections.defaultdict(set); shells=collections.Counter()
for f in glob.glob(str(H/'.cache/oxide/agent-eval/runs/*/*/events.jsonl')):
    run=f.split('/')[-2]
    for l in open(f):
        if not l.startswith('{'): continue
        e=json.loads(l)
        if e.get('type')!='tool_use': continue
        p=e['part']; inp=p['state'].get('input',{}); st=p['state'].get('status')
        if p['tool'] in ('write','edit'):
            writes[inp.get('path','')].add((run,p['tool'],st))
        elif p['tool']=='patch':
            for m in re.findall(r'\*\*\* (?:Update|Add|Delete) File: (\S+)', inp.get('patchText','')):
                writes[m].add((run,'patch',st))
        elif p['tool']=='shell':
            c=inp.get('command',''); wd=inp.get('workdir','')
